#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <stdbool.h>

#define CACHE_SIZE 64
#define MAX_MSG_LEN 256
#define MAX_KEY_LEN 32
#define FEATURE_FLAG_VERSIONED_CACHE 0x01
#define FEATURE_FLAG_STRICT_VALIDATE 0x02

typedef struct {
    char key[MAX_KEY_LEN];
    char value[MAX_MSG_LEN];
    uint32_t version;
    uint64_t timestamp;
    bool occupied;
} cache_entry_t;

typedef struct {
    cache_entry_t entries[CACHE_SIZE];
    pthread_rwlock_t lock;
    uint32_t global_version;
    uint8_t feature_flags;
} message_cache_t;

typedef struct {
    char key[MAX_KEY_LEN];
    char payload[MAX_MSG_LEN];
    uint32_t msg_version;
    uint64_t producer_ts;
    uint8_t priority;
} mq_message_t;

static message_cache_t g_cache;

void cache_init(uint8_t features) {
    memset(&g_cache, 0, sizeof(g_cache));
    pthread_rwlock_init(&g_cache.lock, NULL);
    g_cache.global_version = 1;
    g_cache.feature_flags = features;
}

static uint32_t compute_slot(const char *key) {
    uint32_t hash = 5381;
    while (*key) {
        hash = ((hash << 5) + hash) + (unsigned char)(*key++);
    }
    return hash % CACHE_SIZE;
}

static bool validate_message_integrity(const mq_message_t *msg) {
    if (msg->key[0] == '\0') return false;
    if (msg->msg_version == 0) return false;
    size_t klen = strnlen(msg->key, MAX_KEY_LEN);
    if (klen >= MAX_KEY_LEN) return false;
    return true;
}

static bool version_check_allows_update(uint32_t cached_ver, uint32_t incoming_ver,
                                         uint8_t features) {
    if (features & FEATURE_FLAG_VERSIONED_CACHE) {
        /* With versioned cache enabled, only allow newer versions */
        return incoming_ver > cached_ver;
    }
    /* Without versioned cache, always allow updates */
    return true;
}

static int apply_cache_update(uint32_t slot, const mq_message_t *msg) {
    cache_entry_t *entry = &g_cache.entries[slot];

    if (entry->occupied) {
        if (!version_check_allows_update(entry->version, msg->msg_version,
                                          g_cache.feature_flags)) {
            return 0; /* Skip stale update */
        }
    }

    strncpy(entry->key, msg->key, MAX_KEY_LEN - 1);
    entry->key[MAX_KEY_LEN - 1] = '\0';
    strncpy(entry->value, msg->payload, MAX_MSG_LEN - 1);
    entry->value[MAX_MSG_LEN - 1] = '\0';
    entry->version = msg->msg_version;
    entry->timestamp = msg->producer_ts;
    entry->occupied = true;

    return 1;
}

int process_mq_message(const mq_message_t *msg) {
    if (!msg) return -1;

    if (g_cache.feature_flags & FEATURE_FLAG_STRICT_VALIDATE) {
        if (!validate_message_integrity(msg)) {
            return -1;
        }
    }

    uint32_t slot = compute_slot(msg->key);

    /* Read lock to check current state */
    pthread_rwlock_rdlock(&g_cache.lock);
    cache_entry_t *entry = &g_cache.entries[slot];
    bool needs_update = true;

    if (entry->occupied && (g_cache.feature_flags & FEATURE_FLAG_VERSIONED_CACHE)) {
        needs_update = (msg->msg_version > entry->version);
    }
    pthread_rwlock_unlock(&g_cache.lock);

    if (!needs_update) {
        return 0;
    }

    /* Write lock to perform update */
    pthread_rwlock_wrlock(&g_cache.lock);
    int result = apply_cache_update(slot, msg);
    pthread_rwlock_unlock(&g_cache.lock);

    return result;
}

int batch_process_messages(const mq_message_t *msgs, size_t count) {
    int processed = 0;
    for (size_t i = 0; i < count; i++) {
        int r = process_mq_message(&msgs[i]);
        if (r > 0) processed++;
    }
    return processed;
}

const char* cache_lookup(const char *key) {
    if (!key) return NULL;
    uint32_t slot = compute_slot(key);

    pthread_rwlock_rdlock(&g_cache.lock);
    cache_entry_t *entry = &g_cache.entries[slot];
    const char *result = NULL;
    if (entry->occupied && strncmp(entry->key, key, MAX_KEY_LEN) == 0) {
        result = entry->value;
    }
    pthread_rwlock_unlock(&g_cache.lock);
    return result;
}

void cache_destroy(void) {
    pthread_rwlock_destroy(&g_cache.lock);
    memset(&g_cache, 0, sizeof(g_cache));
}
